mapper.select:
/*selectMasterMpDsItemResultPopList*/ SELECT MAX(Z.AGENT_NAME) AS AGENT_NAME, DECODE(SUM(DECODE(D.APPEAR_VAL,'R',1,0)),0,'0','1') AS APPEAR_VAL, DECODE(SUM(DECODE(D.APPEAR_VAL,'R',1,0)),0,'0','1')*2 AS APPEAR_VAL_CNT, DECODE(SUM(DECODE(D.SIZE_VAL,'R',1,0)),0,'0','1') AS SIZE_VAL, DECODE(SUM(DECODE(D.SIZE_VAL,'R',1,0)),0,'0','1')*1 AS SIZE_VAL_CNT, DECODE(SUM(DECODE(D.MATTER_VAL,'R',1,0)),0,'0','1') AS MATTER_VAL, DECODE(SUM(DECODE(D.MATTER_VAL,'R',1,0)),0,'0','1')*1 AS MATTER_VAL_CNT, DECODE(SUM(DECODE(D.WEIGHT_VAL,'R',1,0)),0,'0','1') AS WEIGHT_VAL, DECODE(SUM(DECODE(D.WEIGHT_VAL,'R',1,0)),0,'0','1')*1 AS WEIGHT_VAL_CNT, DECODE(SUM(DECODE(D.CAPACITY_VAL,'R',1,0)),0,'0','1') AS CAPACITY_VAL, DECODE(SUM(DECODE(D.CAPACITY_VAL,'R',1,0)),0,'0','1')*1 AS CAPACITY_VAL_CNT, DECODE(SUM(DECODE(D.DENSITY_VAL,'R',1,0)),0,'0','1') AS DENSITY_VAL, DECODE(SUM(DECODE(D.DENSITY_VAL,'R',1,0)),0,'0','1')*1 AS DENSITY_VAL_CNT, DECODE(SUM(DECODE(D.COMPRESSION_F,'R',1,0)),0,'0','1') AS COMPRESSION_F, DECODE(SUM(DECODE(D.COMPRESSION_F,'R',1,0)),0,'0','1')*1 AS COMPRESSION_F_CNT, DECODE(SUM(DECODE(D.DISRUPTION_F,'R',1,0)),0,'0','1') AS DISRUPTION_F, DECODE(SUM(DECODE(D.DISRUPTION_F,'R',1,0)),0,'0','1')*1 AS DISRUPTION_F_CNT, DECODE(SUM(DECODE(D.MOISTURE_F,'R',1,0)),0,'0','1') AS MOISTURE_F, DECODE(SUM(DECODE(D.MOISTURE_F,'R',1,0)),0,'0','1')*1 AS MOISTURE_F_CNT, MAX(Z.RATE) AS RATE , SUM(DECODE(D.UD_CODE,'R',1,0)) AS RETRUN, D.AGENT FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = Y.AGENT) AS AGENT_NAME, ROUND(NVL(X.CNT,0)/Y.CNT*100,2)||'%' AS RATE, Y.AGENT AS AGENT FROM (SELECT DBEP.AGENT AS AGENT, COUNT(DISTINCT DBEP.BYCA_COMORG_CODE|| DBEP.BUYER|| DBEP.PLANT_CODE|| DBEP.LEGACY_PO_NO|| DBEP.LEGACY_PO_SEQ|| DBEP.PO_NO|| DBEP.PO_SEQ|| DBEP.LEGACY_GR_NO|| DBEP.LEGACY_GR_SEQ|| DBEP.GR_NO|| DBEP.GR_SEQ) AS CNT
FROM ICOMGRDT GRDT, ICOMPODT PODT, ICOMPOHD POHD, DONGDBEP DBEP WHERE GRDT.BUYER = #{st_com_code} AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ = PODT.PO_SEQ AND GRDT.STATUS <> 'D' AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND GRDT.BUYER = DBEP.BUYER AND GRDT.PO_NO = DBEP.PO_NO AND GRDT.PO_SEQ = DBEP.PO_SEQ AND GRDT.GR_NO = DBEP.GR_NO AND GRDT.GR_SEQ = DBEP.GR_SEQ AND DBEP.PLANT_CODE IN ('2210','2220','5210') AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PODT.RD_DATE >= GRDT.GR_DATE GROUP BY DBEP.AGENT) X, ( SELECT DBEP.AGENT AS AGENT, COUNT(DISTINCT DBEP.BYCA_COMORG_CODE|| DBEP.BUYER|| DBEP.PLANT_CODE|| DBEP.LEGACY_PO_NO|| DBEP.LEGACY_PO_SEQ|| DBEP.PO_NO|| DBEP.PO_SEQ|| DBEP.LEGACY_GR_NO|| DBEP.LEGACY_GR_SEQ|| DBEP.GR_NO|| DBEP.GR_SEQ) AS CNT
FROM ICOMGRDT GRDT, ICOMPODT PODT, ICOMPOHD POHD, DONGDBEP DBEP WHERE GRDT.BUYER = #{st_com_code} AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ = PODT.PO_SEQ AND GRDT.STATUS <> 'D' AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND GRDT.BUYER = DBEP.BUYER AND GRDT.PO_NO = DBEP.PO_NO AND GRDT.PO_SEQ = DBEP.PO_SEQ AND GRDT.GR_NO = DBEP.GR_NO AND GRDT.GR_SEQ = DBEP.GR_SEQ AND DBEP.PLANT_CODE IN ('2210','2220','5210') AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
GROUP BY DBEP.AGENT) Y WHERE X.AGENT(+) = Y.AGENT) Z, DONGDBEP D WHERE Z.AGENT = D.AGENT AND D.PLANT_CODE IN ('2210','2220','5210') AND D.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date} GROUP BY D.AGENT
